exports.init = (params, rng) => {
  const dt = 0.002;
  const theta = params.initialAngle;
  const omega = 0;
  const L = params.length;
  const g = params.g;
  const mass = params.mass;
  const energy = 0.5 * mass * Math.pow(L * omega, 2) + mass * g * L * (1 - Math.cos(theta));
  return {
    theta: theta,
    omega: omega,
    t: 0,
    dt: dt,
    lastTheta: theta,
    lastCrossTime: null,
    period: 0,
    oscillationCount: 0,
    currentAngle: theta,
    currentSpeed: 0,
    energy: energy
  };
};
exports.step = (state, params, rng) => {
  const dt = state.dt;
  const L = params.length;
  const g = params.g;
  const mass = params.mass;
  let theta = state.theta;
  let omega = state.omega;
  let t = state.t;
  function accel(th) {
    if (L === 0) return 0;
    return -(g / L) * Math.sin(th);
  }
  let k1_theta = omega;
  let k1_omega = accel(theta);
  let th2 = theta + 0.5 * dt * k1_theta;
  let om2 = omega + 0.5 * dt * k1_omega;
  let k2_theta = om2;
  let k2_omega = accel(th2);
  let th3 = theta + 0.5 * dt * k2_theta;
  let om3 = omega + 0.5 * dt * k2_omega;
  let k3_theta = om3;
  let k3_omega = accel(th3);
  let th4 = theta + dt * k3_theta;
  let om4 = omega + dt * k3_omega;
  let k4_theta = om4;
  let k4_omega = accel(th4);
  let newTheta = theta + dt / 6 * (k1_theta + 2 * k2_theta + 2 * k3_theta + k4_theta);
  let newOmega = omega + dt / 6 * (k1_omega + 2 * k2_omega + 2 * k3_omega + k4_omega);
  let newT = t + dt;
  let lastTheta = state.lastTheta;
  let lastCrossTime = state.lastCrossTime;
  let period = state.period;
  let oscillationCount = state.oscillationCount;
  if (lastTheta < 0 && newTheta >= 0 && newOmega > 0) {
    let denom = newTheta - lastTheta;
    let frac = denom !== 0 ? (0 - lastTheta) / denom : 0;
    let crossTime = t + dt * frac;
    if (lastCrossTime !== null) {
      period = crossTime - lastCrossTime;
      oscillationCount += 1;
    }
    lastCrossTime = crossTime;
  }
  let currentAngle = newTheta;
  let currentSpeed = Math.abs(newOmega * L);
  let energy = 0.5 * mass * Math.pow(L * newOmega, 2) + mass * g * L * (1 - Math.cos(newTheta));
  return {
    theta: newTheta,
    omega: newOmega,
    t: newT,
    dt: dt,
    lastTheta: newTheta,
    lastCrossTime: lastCrossTime,
    period: period,
    oscillationCount: oscillationCount,
    currentAngle: currentAngle,
    currentSpeed: currentSpeed,
    energy: energy
  };
};
exports.observe = (state, params) => {
  return {
    period: state.period,
    oscillationCount: state.oscillationCount,
    currentAngle: state.currentAngle,
    bobSpeed: state.currentSpeed,
    swingEnergy: state.energy
  };
};
exports.view = (state, params) => {
  const L = params.length;
  const pivotX = 5;
  const pivotY = 8.5;
  const scale = 1.6;
  const absT = Math.abs(state.theta);
  let gain;
  if (absT <= 0.25) gain = 3.5;
  else if (absT >= 1.2) gain = 1;
  else gain = 3.5 - (absT - 0.25) * (2.5 / 0.95);
  const displayTheta = state.theta * gain;
  const bobX = pivotX + Math.sin(displayTheta) * L * scale;
  const bobY = pivotY - Math.cos(displayTheta) * L * scale;
  const bobRadius = 0.25 + 0.08 * params.mass;
  const speed = state.currentSpeed;
  const norm = Math.min(1, speed / 1.6);
  const r1 = 58, g1 = 123, b1 = 213;
  const r2 = 231, g2 = 76, b2 = 60;
  const r = Math.round(r1 + (r2 - r1) * norm);
  const gcol = Math.round(g1 + (g2 - g1) * norm);
  const b = Math.round(b1 + (b2 - b1) * norm);
  const toHex = (v) => v.toString(16).padStart(2, '0');
  const color = '#' + toHex(r) + toHex(gcol) + toHex(b);
  const bodies = [];
  bodies.push({ id: 'pivot', x: pivotX, y: pivotY, radius: 0.14, color: '#2c3e50' });
  for (let i = 1; i <= 4; i++) {
    const f = i / 5;
    const sx = pivotX + Math.sin(displayTheta) * L * scale * f;
    const sy = pivotY - Math.cos(displayTheta) * L * scale * f;
    bodies.push({ id: 'string' + i, x: sx, y: sy, radius: 0.06, color: '#b08d57' });
  }
  bodies.push({ id: 'bob', x: bobX, y: bobY, radius: bobRadius, color: color });
  return {
    kind: 'bodies',
    bounds: { x: 0, y: 0, w: 10, h: 10 },
    bodies: bodies
  };
};
